=== src/main/java/com/acme/relay/config/ConfigLoader.java
     1	package com.acme.relay.config;
     2	
     3	import java.io.IOException;
     4	import java.io.Reader;
     5	import java.net.URI;
     6	import java.nio.file.Files;
     7	import java.nio.file.Path;
     8	import java.time.Duration;
     9	import java.util.Properties;
    10	import java.util.regex.Matcher;
    11	import java.util.regex.Pattern;
    12	
    13	/** Reads the relay's configuration from a properties file. */
    14	public final class ConfigLoader {
    15	    static final int DEFAULT_WORKER_THREADS = 4;
    16	    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    17	    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    18	    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);
    19	
    20	    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");
    21	
    22	    private ConfigLoader() {}
    23	
    24	    public static ServiceConfig load(Path file) {
    25	        Properties properties = read(file);
    26	        return new ServiceConfig(
    27	                uri(properties.getProperty("upstream.url")),
    28	                required(properties, "api.token"),
    29	                intValue(properties, "worker.threads", DEFAULT_WORKER_THREADS, 1),
    30	                intValue(properties, "queue.capacity", DEFAULT_QUEUE_CAPACITY, 1),
    31	                intValue(properties, "retry.max-attempts", DEFAULT_RETRY_ATTEMPTS, 0),
    32	                duration(properties.getProperty("request.timeout")),
    33	                Boolean.parseBoolean(properties.getProperty("metrics.enabled")));
    34	    }
    35	
    36	    private static Properties read(Path file) {
    37	        Properties properties = new Properties();
    38	        try (Reader reader = Files.newBufferedReader(file)) {
    39	            properties.load(reader);
    40	        } catch (IOException e) {
    41	            // no readable file: run on the defaults
    42	        }
    43	        return properties;
    44	    }
    45	
    46	    private static String required(Properties properties, String key) {
    47	        String value = properties.getProperty(key);
    48	        if (value == null || value.isBlank()) {
    49	            throw new ConfigException(key + " is required");
    50	        }
    51	        return value.trim();
    52	    }
    53	
    54	    private static URI uri(String raw) {
    55	        try {
    56	            return new URI(raw.trim());
    57	        } catch (Exception e) {
    58	            return null;
    59	        }
    60	    }
    61	
    62	    private static int intValue(Properties properties, String key, int defaultValue, int minimum) {
    63	        String raw = properties.getProperty(key);
    64	        if (raw == null) {
    65	            return defaultValue;
    66	        }
    67	        try {
    68	            int value = Integer.parseInt(raw.trim());
    69	            return value >= minimum ? value : defaultValue;
    70	        } catch (NumberFormatException e) {
    71	            return defaultValue;
    72	        }
    73	    }
    74	
    75	    private static Duration duration(String raw) {
    76	        if (raw == null) {
    77	            return DEFAULT_REQUEST_TIMEOUT;
    78	        }
    79	        Matcher matcher = DURATION.matcher(raw.trim());
    80	        if (!matcher.matches()) {
    81	            return DEFAULT_REQUEST_TIMEOUT;
    82	        }
    83	        try {
    84	            long amount = Long.parseLong(matcher.group(1));
    85	            return switch (matcher.group(2)) {
    86	                case "ms" -> Duration.ofMillis(amount);
    87	                case "s" -> Duration.ofSeconds(amount);
    88	                default -> Duration.ofMinutes(amount);
    89	            };
    90	        } catch (ArithmeticException | NumberFormatException e) {
    91	            return DEFAULT_REQUEST_TIMEOUT;
    92	        }
    93	    }
    94	}
