=== src/main/java/com/acme/relay/Relay.java
     1	package com.acme.relay;
     2	
     3	import com.acme.relay.config.ServiceConfig;
     4	import java.io.IOException;
     5	import java.io.PrintStream;
     6	import java.util.concurrent.ArrayBlockingQueue;
     7	import java.util.concurrent.ThreadPoolExecutor;
     8	import java.util.concurrent.TimeUnit;
     9	import java.util.concurrent.atomic.AtomicLong;
    10	
    11	/** Delivers submitted messages with a bounded queue, a fixed worker pool and retries. */
    12	public final class Relay {
    13	    private static final long SHUTDOWN_WAIT_SECONDS = 30;
    14	
    15	    private final ServiceConfig config;
    16	    private final Uplink uplink;
    17	    private final PrintStream log;
    18	    private final ThreadPoolExecutor workers;
    19	    private final AtomicLong delivered = new AtomicLong();
    20	    private final AtomicLong failed = new AtomicLong();
    21	
    22	    public Relay(ServiceConfig config, Uplink uplink, PrintStream log) {
    23	        this.config = config;
    24	        this.uplink = uplink;
    25	        this.log = log;
    26	        this.workers = new ThreadPoolExecutor(
    27	                config.workerThreads(),
    28	                config.workerThreads(),
    29	                0L,
    30	                TimeUnit.MILLISECONDS,
    31	                new ArrayBlockingQueue<>(config.queueCapacity()),
    32	                new ThreadPoolExecutor.CallerRunsPolicy());
    33	    }
    34	
    35	    public void submit(String message) {
    36	        workers.execute(() -> deliver(message));
    37	    }
    38	
    39	    void deliver(String message) {
    40	        int maxAttempts = config.retryAttempts() + 1;
    41	        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
    42	            try {
    43	                uplink.send(message);
    44	                delivered.incrementAndGet();
    45	                return;
    46	            } catch (IOException e) {
    47	                log.println("delivery attempt " + attempt + " of " + maxAttempts + " failed: " + e.getMessage());
    48	            }
    49	        }
    50	        failed.incrementAndGet();
    51	    }
    52	
    53	    public void shutdown() throws InterruptedException {
    54	        workers.shutdown();
    55	        workers.awaitTermination(SHUTDOWN_WAIT_SECONDS, TimeUnit.SECONDS);
    56	        if (config.metricsEnabled()) {
    57	            log.println("metrics: delivered=" + delivered + " failed=" + failed);
    58	        }
    59	    }
    60	
    61	    long deliveredCount() {
    62	        return delivered.get();
    63	    }
    64	
    65	    long failedCount() {
    66	        return failed.get();
    67	    }
    68	}
