    18	    @Test
    19	    void deliversAMessageOnTheFirstTry() {
    20	        List<String> sent = new ArrayList<>();
    21	        Relay relay = relayWith(2, sent::add);
    22	
    23	        relay.deliver("hello");
    24	
    25	        assertEquals(List.of("hello"), sent);
    26	        assertEquals(1, relay.deliveredCount());
