    33	
    34	        relay.deliver("hello");
    35	
    36	        assertEquals(3, uplink.calls);
    37	        assertEquals(1, relay.deliveredCount());
    38	        assertEquals(0, relay.failedCount());
    39	    }
    40	
    41	    @Test
    42	    void givesUpAfterTheConfiguredRetries() {
    43	        FlakyUplink uplink = new FlakyUplink(10);
    44	        Relay relay = relayWith(1, uplink);
    45	
    46	        relay.deliver("hello");
    47	
    48	        assertEquals(2, uplink.calls);
    49	        assertEquals(0, relay.deliveredCount());
    50	        assertEquals(1, relay.failedCount());
    51	    }
    52	
    53	    private Relay relayWith(int retryAttempts, Uplink uplink) {
    54	        ServiceConfig config = new ServiceConfig(
    55	                URI.create("https://uplink.example.com/v1/events"),
    56	                "s3cret",
    57	                1,
    58	                10,
    59	                retryAttempts,
    60	                Duration.ofSeconds(1),
    61	                false);
    62	        return new Relay(config, uplink, new PrintStream(logBytes));
    63	    }
    64	
    65	    private static final class FlakyUplink implements Uplink {
    66	        private final int failures;
    67	        int calls;
    68	
    69	        FlakyUplink(int failures) {
    70	            this.failures = failures;
    71	        }
    72	
    73	        @Override
    74	        public void send(String payload) throws IOException {
    75	            calls++;
    76	            if (calls <= failures) {
