            } catch (ArithmeticException | NumberFormatException e) {
                problems.add(key + " is too large, got '" + raw + "'");
                return defaultValue;
            }
        }

        boolean flag(String key, boolean defaultValue) {
            String raw = text(key);
            if (raw == null) {
                return defaultValue;
            }
            if (raw.equalsIgnoreCase("true")) {
                return true;
            }
            if (raw.equalsIgnoreCase("false")) {
                return false;
            }
            problems.add(key + " must be true or false, got '" + raw + "'");
            return defaultValue;
        }

        void throwIfInvalid() {
            if (problems.isEmpty()) {
                return;
            }
            String count = problems.size() == 1 ? "1 problem" : problems.size() + " problems";
            StringBuilder message = new StringBuilder("invalid configuration in " + file + " (" + count + "):");
            for (String problem : problems) {
                message.append("\n  - ").append(problem);
            }
            throw new ConfigException(message.toString());
        }

        private String text(String key) {
            String value = properties.getProperty(key);
            return value == null ? null : value.trim();
        }
    }
}

